def sgmv(y, x, W, s):
    # rows s[i] to s[i+1]-1 all use weight W[i]
    for i in range(len(W)):
        lo, hi = s[i], s[i + 1]
        y[lo:hi] += x[lo:hi] @ W[i]
    return y

def multi_lora(x, W0, A, B, s, r, scale):
    y = x @ W0                       # one GEMM, whole batch
    v = sgmv(zeros(len(x), r), x, A, s)   # shrink to rank r
    return sgmv(y, scale * v, B, s)       # expand, add in place
